head.b:skin:
:root {
  --gold: #c9a86c;
  --gold-dark: #b08d4f;
  --beige: #f8f1e3;
  --cream: #fdfaf5;
  --dark: #2c2416;
  --text: #4a4033;
  --white: #ffffff;
  --shadow: 0 10px 40px rgba(201,168,108,0.15);
  --radius: 16px;
  --transition: all 0.3s ease;
}

*,*::before,*::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: 'Poppins', sans-serif;
  font-size: 16px;
  line-height: 1.7;
  color: var(--text);
  background: var(--cream);
  overflow-x: hidden;
}
img { max-width: 100%; height: auto; display: block; }
a { text-decoration: none; color: inherit; transition: var(--transition); }

/* --- CSS FORM BOOKING TERISOLASI --- */
.dd-booking-container {
  max-width: 560px;
  margin: 30px auto;
  background: #fff;
  padding: 28px;
  border-radius: 16px;
  box-shadow: 0 5px 20px rgba(0,0,0,.08);
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  box-sizing: border-box;
}
.dd-booking-container *, .dd-booking-container *::before, .dd-booking-container *::after {
  box-sizing: border-box;
}
.dd-booking-container h3 {
  margin: 0 0 8px;
  text-align: center;
  color: #243a32;
  font-size: 24px;
}
.dd-booking-subtitle {
  margin: 0 0 25px;
  text-align: center;
  color: #777;
  font-size: 14px;
}
.dd-booking-group { margin-bottom: 18px; }
.dd-booking-group label {
  display: block;
  margin-bottom: 7px;
  color: #444;
  font-size: 14px;
  font-weight: 600;
}
.dd-booking-group input,
.dd-booking-group select,
.dd-booking-group textarea {
  width: 100%;
  padding: 12px 14px;
  border: 1px solid #ddd;
  border-radius: 9px;
  background: #fff;
  color: #333;
  font-family: inherit;
  font-size: 14px;
  outline: none;
}
.dd-booking-price {
  display: none;
  margin-top: 10px;
  padding: 14px;
  border-radius: 10px;
  background: #f1faf6;
  border: 1px solid #d7eee4;
}
.dd-booking-price.show { display: block; }
.dd-booking-price-label { display: block; margin-bottom: 4px; color: #777; font-size: 12px; }
.dd-booking-price-value { display: block; color: #174d3e; font-size: 22px; font-weight: 800; }
.dd-booking-gps {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 11px 15px;
  border: 1px solid #ccd0d5;
  border-radius: 9px;
  background: #f3f5f6;
  color: #333;
  font-weight: 600;
  cursor: pointer;
  margin-bottom: 8px;
}
.dd-booking-submit {
  width: 100%;
  padding: 14px;
  border: 0;
  border-radius: 9px;
  background: #25d366;
  color: #fff;
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
}
.dd-booking-submit:hover { background: #1ebe5d; }
.dd-booking-note { margin-top: 12px; text-align: center; color: #888; font-size: 11px; }

.blog-posts, .post-footer, .post-share-buttons { display: none !important; }
#blog-pager { display: none; }

body.script:
//
(function () {
  "use strict";

  var services = {
    "Face Acupressure + Tradisional Massage": {
      "90 Menit": 350000,
      "120 Menit": 400000
    },
    "Kerok + Tradisional Massage": {
      "90 Menit": 350000,
      "120 Menit": 400000
    },
    "Scrub + Tradisional Massage": {
      "90 Menit": 350000,
      "120 Menit": 400000
    },
    "Sport Massage": {
      "90 Menit": 400000,
      "120 Menit": 450000
    },
    "Refleksiology + Tradisional Massage": {
      "90 Menit": 350000,
      "120 Menit": 400000
    },
    "Tradisional Massage + Dry Cupping": {
      "90 Menit": 400000,
      "120 Menit": 500000
    },
    "Thai Massage": {
      "90 Menit": 400000,
      "120 Menit": 450000
    },
    "Deeptissue Massage": {
      "90 Menit": 400000,
      "120 Menit": 450000
    },
    "Hot Stone Massage": {
      "90 Menit": 500000,
      "120 Menit": 600000
    },
    "Balinese Massage": {
      "90 Menit": 350000,
      "120 Menit": 400000
    },
    "Aromaterapi Massage": {
      "90 Menit": 400000,
      "120 Menit": 500000
    },
    "Swedish Massage": {
      "90 Menit": 350000,
      "120 Menit": 400000
    },
    "Dry Massage": {
      "60 Menit": 300000,
      "90 Menit": 400000
    },
    "Sensual Massage": {
      "90 Menit": 1200000
    },
    "Body to Body Massage": {
      "90 Menit": 1400000
    }
  };

  var adminPhone = "6285217344735";

  var serviceSelect = document.getElementById("ddService");
  var durationSelect = document.getElementById("ddDuration");
  var priceBox = document.getElementById("ddPriceBox");
  var priceText = document.getElementById("ddPrice");
  var gpsButton = document.getElementById("ddGpsButton");
  var mapLocation = document.getElementById("ddMapLocation");
  var scheduleDateSelect = document.getElementById("ddScheduleDate");
  var scheduleTimeInput = document.getElementById("ddScheduleTime");
  var form = document.getElementById("ddBookingForm");

  function formatRupiah(value) {
    return new Intl.NumberFormat("id-ID", {
      style: "currency",
      currency: "IDR",
      maximumFractionDigits: 0
    }).format(value);
  }

  function generateScheduleDates() {
    var daysIndo = ["Minggu", "Senin", "Selasa", "Rabu", "Kamis", "Jumat", "Sabtu"];
    var monthsIndo = ["01", "02", "03", "04", "05", "06", "07", "08", "09", "10", "11", "12"];
    var today = new Date();

    for (var i = 0; i < 7; i++) {
      var d = new Date();
      d.setDate(today.getDate() + i);

      var dayName = daysIndo[d.getDay()];
      var day = String(d.getDate()).padStart(2, '0');
      var month = monthsIndo[d.getMonth()];
      var year = d.getFullYear();

      var formattedDate = dayName + ", " + day + "/" + month + "/" + year;
      var labelText = formattedDate;
      if (i === 0) {
        labelText += " (Hari Ini)";
      } else if (i === 1) {
        labelText += " (Besok)";
      }

      var option = document.createElement("option");
      option.value = formattedDate;
      option.textContent = labelText;
      scheduleDateSelect.appendChild(option);
    }
  }

  generateScheduleDates();

  var serviceKeys = Object.keys(services);
  for (var j = 0; j < serviceKeys.length; j++) {
    var serviceName = serviceKeys[j];
    var option = document.createElement("option");
    option.value = serviceName;
    option.textContent = serviceName;
    serviceSelect.appendChild(option);
  }

  serviceSelect.addEventListener("change", function () {
    var service = serviceSelect.value;
    durationSelect.innerHTML = "";
    priceBox.classList.remove("show");
    priceText.textContent = "Rp0";

    if (!service) {
      durationSelect.disabled = true;
      var option = document.createElement("option");
      option.value = "";
      option.textContent = "-- Pilih Layanan Terlebih Dahulu --";
      durationSelect.appendChild(option);
      return;
    }

    durationSelect.disabled = false;
    var firstOption = document.createElement("option");
    firstOption.value = "";
    firstOption.textContent = "-- Pilih Durasi --";
    durationSelect.appendChild(firstOption);

    var durationKeys = Object.keys(services[service]);
    for (var k = 0; k < durationKeys.length; k++) {
      var durationName = durationKeys[k];
      var opt = document.createElement("option");
      opt.value = durationName;
      opt.textContent = durationName + " — " + formatRupiah(services[service][durationName]);
      durationSelect.appendChild(opt);
    }
  });

  durationSelect.addEventListener("change", function () {
    var service = serviceSelect.value;
    var duration = durationSelect.value;

    if (service && duration && services[service] && services[service][duration]) {
      var price = services[service][duration];
      priceText.textContent = formatRupiah(price);
      priceBox.classList.add("show");
    } else {
      priceBox.classList.remove("show");
    }
  });

  gpsButton.addEventListener("click", function () {
    if (!navigator.geolocation) {
      alert("Geolocation tidak didukung oleh browser perangkat ini.");
      return;
    }

    gpsButton.disabled = true;
    gpsButton.textContent = "📍 Mendapatkan lokasi...";
    mapLocation.value = "Mendapatkan titik GPS terkini...";

    navigator.geolocation.getCurrentPosition(
      function (position) {
        var lat = position.coords.latitude;
        var lon = position.coords.longitude;
        var mapsUrl = "https://maps.google.com/?q=" + lat + "," + lon;

        mapLocation.value = mapsUrl;
        gpsButton.disabled = false;
        gpsButton.textContent = "✅ Titik GPS Berhasil Diambil";
      },
      function (error) {
        alert("Gagal mendapatkan lokasi. Pastikan izin GPS aktif.");
        mapLocation.value = "";
        gpsButton.disabled = false;
        gpsButton.textContent = "📍 Ambil Titik Maps dari HP Saya";
      },
      { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
    );
  });

  form.addEventListener("submit", function (event) {
    event.preventDefault();

    var name = document.getElementById("ddClientName").value.trim();
    var service = serviceSelect.value;
    var duration = durationSelect.value;
    var therapist = document.getElementById("ddTherapist").value;
    var region = document.getElementById("ddRegion").value;
    var address = document.getElementById("ddAddress").value.trim();
    var map = mapLocation.value.trim();

    var selectedDate = scheduleDateSelect.value;
    var selectedTime = scheduleTimeInput.value.trim();
    var scheduleFinal = selectedDate + " - " + selectedTime;

    if (!service || !duration) {
      alert("Silakan lengkapi layanan dan durasi.");
      return;
    }

    var price = services[service][duration];

    var message = "*FORMULIR ORDER PIJAT PANGGILAN - DAYDREAMS MASSAGE*\n\n" +
                  "*Tujuan Admin:* Admin 2 (Mr.Erik)\n\n" +
                  "━━━━━━━━━━━━━━━━━━━━\n\n" +
                  "👤 *Nama Pemesan:*\n" + name + "\n\n" +
                  "💆 *Pilihan Layanan:*\n" + service + "\n\n" +
                  "⏱️ *Durasi:*\n" + duration + "\n\n" +
                  "💰 *Estimasi Tarif:*\n" + formatRupiah(price) + "\n\n" +
                  "👥 *Preferensi Terapis:*\n" + therapist + "\n\n" +
                  "📍 *Wilayah:*\n" + region + "\n\n" +
                  "🏢 *Lokasi Hotel/Kamar/Alamat:*\n" + address + "\n\n" +
                  "🗺️ *Titik Maps GPS:*\n" + (map || "Tidak melampirkan titik GPS") + "\n\n" +
                  "🕒 *Waktu Panggilan:*\n" + scheduleFinal + "\n\n" +
                  "━━━━━━━━━━━━━━━━━━━━\n\n" +
                  "Mohon konfirmasi ketersediaan terapis dan total tarifnya.\n" +
                  "https://daydreamsjakartamassage.blogspot.com/\n" +
                  "Terima kasih!";

    var waUrl = "https://wa.me/" + adminPhone + "?text=" + encodeURIComponent(message);
    window.open(waUrl, "_blank");
  });

})();
//
